const H_DENOM: u32 = 1000000000;

#[derive(Clone, Copy)]
struct State {
    credited: u128,
}

// ============================================================================
// Transition functions (from qedspec operations — effects + guards)
//
// Each returns true if the guard passes and the transition fires,
// false if the guard rejects the operation.
// ============================================================================

fn convert(s: &mut State, matured: u128, h: u128) -> bool {
    if !((h <= 1000000000)) {
        return false;
    }
    s.credited = (haircut_credit (matured) (h));
    true
}

// ============================================================================
// Reference implementations (from qedspec ref_impl declarations).
// ============================================================================

fn haircut_credit(matured: u128, h: u128) -> u128 {
    (matured * h) / 1000000000
}

// ============================================================================
// Guard enforcement — transitions reject invalid inputs
// ============================================================================

#[kani::proof]
#[kani::unwind(2)]
#[kani::solver(cadical)]
fn verify_convert_rejects_invalid() {
    let mut s = State {
        credited: kani::any(),
    };
    let matured: u128 = kani::any();
    let h: u128 = kani::any();
    kani::assume(!((h <= 1000000000)));
    kani::cover!(true, "guard-violation domain is satisfiable");
    assert!(!convert(&mut s, matured, h),
        "convert must reject when guard is violated");
}

